// spec: .qa/e2e/specs/stories-viewer.md (раздел 1) · кейсы .qa/tests/stories-viewer/SV-01,02,05,06,07,10,11
// Только просмотр: ничего не создаёт и не отправляет. Зритель reg1 (מסורתי/דתי, мужчина). Ожидаемые данные — из story_feed.
// Предусловие: в ленте reg1 есть активные сторис (их создают тесты @data этого раздела или ручная проверка).
import { test, expect } from '../../fixtures';
import path from 'path';
import { saveSession } from '../_shared/session';
import {
  openDiscover, requireGroups, openAuthor, expectShowing, authorButton, closeButton, menuButton,
  segments, fills, tapSide, storyCircle, storyImage, groupsOf, groupsInRow, SEEN_KEY,
} from './viewer-helpers';

test.use({ storageState: path.resolve(__dirname, '../../../auth/reg1.json') });

test.describe('מסך צפייה בסיפור — просмотр', () => {
  // Один за другим в одном окне-воркере: одна сессия reg1, refresh-токен сохраняется после каждого теста.
  test.describe.configure({ mode: 'default' });
  test.afterEach(async ({ page }) => saveSession(page, 'reg1'));

  test('Открытие из ряда: спиннер и стоящий прогресс до загрузки, затем картинка, автор и время @iphone @prod-safe (#f71f8d)', async ({ page }) => {
    let release!: () => void;
    const gate = new Promise<void>((r) => (release = r));
    await page.route('**/storage/v1/object/public/stories/**', async (route) => {
      await gate;
      await route.continue();
    });
    const [g] = requireGroups(await groupsInRow(page, await openDiscover(page)));
    await openAuthor(page, g);
    expect(page.url()).toContain(`/story/${g.stories[0].id}`);
    // AC 1: пока картинка не загружена — спиннер, прогресс не идёт.
    await expect(page.getByRole('progressbar')).toBeVisible();
    expect((await fills(page, g.name))[0]).toBe(0);
    release();
    await expect(page.getByRole('progressbar')).toHaveCount(0);
    // AC 2–3: картинка сторис, автор (имя + аватар), время.
    await expectShowing(page, g, 0);
    const author = authorButton(page, g.name);
    if (g.avatar) await expect(author.locator(`img[src="${g.avatar}"]`)).toHaveCount(1);
    await expect(page.getByText(/^(לפני .+|עכשיו)$/).first()).toBeVisible();
  });

  test('Прогресс-бар: сегментов столько, сколько сторис у автора, заполнение растёт @iphone @prod-safe (#f71f8d)', async ({ page }) => {
    const groups = requireGroups(await groupsInRow(page, await openDiscover(page)));
    const g = groups.reduce((a, b) => (b.stories.length > a.stories.length ? b : a));
    await openAuthor(page, g);
    await expectShowing(page, g, 0);
    await expect(segments(page, g.name)).toHaveCount(g.stories.length);
    const first = (await fills(page, g.name))[0];
    await expect.poll(async () => (await fills(page, g.name))[0]).toBeGreaterThan(first);
    // Ещё не просмотренные сегменты — пустые.
    const rest = (await fills(page, g.name)).slice(1);
    expect(rest.every((f) => f === 0)).toBe(true);
  });

  test('«✕» закрывает просмотрщик и возвращает в ряд /discover @iphone @prod-safe (#f71f8d)', async ({ page }) => {
    const [g] = requireGroups(await groupsInRow(page, await openDiscover(page)));
    await openAuthor(page, g);
    await expectShowing(page, g, 0);
    await closeButton(page).click();
    await page.waitForURL(/\/discover/);
    await expect(closeButton(page)).toHaveCount(0);
    await expect(storyCircle(page, g.authorId)).toBeVisible();
  });

  test('Конец всех сторис: «צפית בכל הסטוריז», затем возврат в ряд @iphone @prod-safe (#f71f8d)', async ({ page }) => {
    // Просмотрщик идёт по всем непросмотренным авторам ряда (с выбранного дальше и по кругу) — начинаем с первого
    // и проходим все сторис всех авторов в порядке ленты.
    const groups = requireGroups(await groupsInRow(page, await openDiscover(page)));
    await openAuthor(page, groups[0]);
    for (const g of groups) {
      for (let i = 0; i < g.stories.length; i++) {
        await expectShowing(page, g, i);
        await tapSide(page, 'left');
      }
    }
    // AC 10: «מציג חיווי בעת סיום צפייה בכלל הסיפורים הזמינים».
    await expect(page.getByText('צפית בכל הסטוריז')).toBeVisible();
    await page.waitForURL(/\/discover/);
    await expect(closeButton(page)).toHaveCount(0);
    // Р1: просмотренные отмечаются на устройстве (серое кольцо в ряду) — все сторис ленты в «stories.seen».
    const seen: string[] = JSON.parse((await page.evaluate((k) => localStorage.getItem(k), SEEN_KEY)) ?? '[]');
    for (const g of groups) for (const s of g.stories) expect(seen).toContain(s.id);
  });

  test('Имя автора в шапке ведёт в его профиль, «назад» — снова просмотрщик @iphone @prod-safe (#f71f8d)', async ({ page }) => {
    const [g] = requireGroups(await groupsInRow(page, await openDiscover(page)));
    await openAuthor(page, g);
    await expectShowing(page, g, 0);
    await authorButton(page, g.name).click();
    // AC 7: «מאפשר כניסה לפרופיל מפרסם הסיפור».
    await page.waitForURL(new RegExp(`/profile/${g.authorId}`));
    await expect(page.getByText(new RegExp(`^${g.name}, \\d+$`))).toBeVisible();
    await page.goBack();
    await page.waitForURL(/\/story\//);
    await expect(closeButton(page)).toBeVisible();
  });

  test('Меню «⋯»: «דיווח על הסטורי», «חסימת <автор>», «ביטול» закрывает — без отправки @iphone @prod-safe (#f71f8d)', async ({ page }) => {
    const [g] = requireGroups(await groupsInRow(page, await openDiscover(page)));
    await openAuthor(page, g);
    await expectShowing(page, g, 0);
    await menuButton(page).click();
    const sheet = page.getByRole('dialog');
    // AC 9 + Figma 869-8083. Жалобу и блок не нажимаем.
    await expect(sheet.getByText('פעולות על הסטורי')).toBeVisible();
    await expect(sheet.getByRole('button', { name: /דיווח על הסטורי/ })).toBeVisible();
    await expect(sheet.getByRole('button', { name: new RegExp(`חסימת ${g.name}`) })).toBeVisible();
    await sheet.getByRole('button', { name: 'ביטול' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
    await expect(closeButton(page)).toBeVisible();
    await expect(storyImage(page, g.stories[0])).toBeVisible();
  });

  test('Чужая аудитория: сторис религиозных авторов не приходят светскому free и не видны в его ряду @iphone @prod-safe (#f71f8d)', async ({ page, asUser }) => {
    const religious = requireGroups(await groupsInRow(page, await openDiscover(page)));
    const free = await asUser('free');
    try {
      const freeFeed = await openDiscover(free);
      const freeAuthors = new Set(groupsOf(freeFeed).map((g) => g.authorId));
      // #a85b92 «מנגנון חשיפת סיפורים לפי קהל»: аудитории не пересекаются.
      for (const g of religious) expect(freeAuthors.has(g.authorId), `free видит сторис «${g.name}»`).toBe(false);
      await expect(free.getByRole('button', { name: /הסטורי שלי/ })).toBeVisible();
      for (const g of religious) await expect(storyCircle(free, g.authorId)).toHaveCount(0);
    } finally {
      await saveSession(free, 'free');
    }
  });
});
